def sort_negatives_first_then_positives(nums):
    negatives = []
    nonnegatives = []
    for x in nums:
        if x < 0:
            negatives.append(x)
        else:
            nonnegatives.append(x)
    negatives.sort()
    nonnegatives.sort()
    return negatives + nonnegatives

