def meets_min_digit_count_policy(s):
    for ch in s:
        if ch.isspace():
            return False
    if len(s) < 6 or len(s) > 20:
        return False
    digit_count = sum(1 for ch in s if ch.isdigit())
    return digit_count >= 2

