def oxford_join(items):
    count = len(items)
    if count == 0:
        return ''
    if count == 1:
        return items[0]
    if count == 2:
        return items[0] + ' and ' + items[1]
    return ', '.join(items[:-1]) + ', and ' + items[-1]

def subtract_days_from_date(y, m, d, n):
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    def dim(year, month):
        if month == 2 and is_leap(year):
            return 29
        return days_in_month[month - 1]
    cy, cm, cd = y, m, d
    remaining = n
    if remaining >= 0:
        while remaining > 0:
            if cd > remaining:
                cd -= remaining
                remaining = 0
            else:
                remaining -= cd
                cm -= 1
                if cm == 0:
                    cm = 12
                    cy -= 1
                cd = dim(cy, cm)
    else:
        add_days = -remaining
        while add_days > 0:
            days_left = dim(cy, cm) - cd
            if add_days <= days_left:
                cd += add_days
                add_days = 0
            else:
                add_days -= days_left + 1
                cm += 1
                if cm == 13:
                    cm = 1
                    cy += 1
                cd = 1
    return (cy, cm, cd)

def find_all_occurrence_indices(s, sub):
    if not sub:
        return []
    result = []
    i = 0
    while i <= len(s) - len(sub):
        if s[i:i + len(sub)] == sub:
            result.append(i)
        i += 1
    return result

