def common_prefix_counts(words, prefix_len):
    counts = {}
    for word in words:
        if len(word) >= prefix_len:
            prefix = word[:prefix_len]
            counts[prefix] = counts.get(prefix, 0) + 1
    return counts

def tokenize_camel_case(s):
    if s == '':
        return []
    words = []
    current = ''
    for ch in s:
        if ch.isupper() and current:
            words.append(current)
            current = ch
        else:
            current += ch
    words.append(current)
    return words

