def interleave_two_sorted_lists(a, b):
    result = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def bucket_sort_by_sign(nums):
    neg = []
    zero = []
    pos = []
    for x in nums:
        if x < 0:
            neg.append(x)
        elif x == 0:
            zero.append(x)
        else:
            pos.append(x)
    neg.sort()
    zero.sort()
    pos.sort()
    return {'negative': neg, 'zero': zero, 'positive': pos}

