def is_valid_hex_grouped(s):
    if not s:
        return False
    groups = s.split('_')
    hex_digits = set('0123456789ABCDEF')
    for g in groups:
        if len(g) != 2:
            return False
        for ch in g:
            if ch not in hex_digits:
                return False
    return True

