def longest_consecutive_alphabetical_run(s):
    if s == "":
        return ""
    best_run = ""
    current_run = s[0]
    for prev_char, curr_char in zip(s, s[1:]):
        if prev_char.isalpha() and curr_char.isalpha() and ord(curr_char.lower()) - ord(prev_char.lower()) == 1:
            current_run += curr_char
        else:
            current_run = curr_char
        if len(current_run) > len(best_run):
            best_run = current_run
    return best_run

