def moving_average_floor(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    window_sum = sum(lst[:k])
    result = [window_sum // k]
    for i in range(k, n):
        window_sum += lst[i] - lst[i - k]
        result.append(window_sum // k)
    return result

